function ttc_day_label(int$d):string{return$d===8?'Chủ nhật':'Thứ '.$d;}
function ttc_matrix(array$days,array$s,array$selected,string$name):void{echo'<div class="matrix-wrap"><table class="busy-grid"><thead><tr><th>Buổi</th><th>Tiết</th>';foreach($days as$d)echo'<th>'.e(ttc_day_label((int)$d)).'</th>';echo'</tr></thead><tbody>';foreach(['Sáng'=>(int)$s['morning_periods'],'Chiều'=>(int)$s['afternoon_periods']]as$session=>$max)for($p=1;$p<=$max;$p++){echo'<tr>';if($p===1)echo'<th rowspan="'.$max.'">'.e($session).'</th>';echo'<th>'.$p.'</th>';foreach($days as$d){$key=ttb_slot_key((int)$d,$session,$p);$on=!empty($selected[$key]);echo'<td><label class="slot-check"><input type="checkbox" name="'.e($name).'[]" value="'.e($key).'" '.($on?'checked':'').'><span><i class="bi bi-x-lg"></i></span></label></td>';}echo'</tr>';}echo'</tbody></table></div>';}
